insert into questions(assessment_id, module_id, stem, options, answer_idx, explanation, family, is_calc, difficulty) values
((select id from assessments where code='GATE_1'),(select id from modules where code='GOV'),'To which authority does a bank file Cash Transaction Reports (CTR) and Suspicious Transaction Reports (STR)?','["Reserve Bank of India", "Financial Intelligence Unit – India (FIU-IND)", "SEBI", "Enforcement Directorate"]'::jsonb,1,'Reporting entities under PMLA report CTRs and STRs to FIU-IND.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='GOV'),'For a company customer, a beneficial owner under the PML Rules is a natural person who ultimately holds an ownership interest of:','["More than 25%", "More than 10%", "More than 51%", "Any shareholding"]'::jsonb,1,'The 2023 amendment lowered the threshold for companies to more than 10%.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='GOV'),'Once the Principal Officer concludes a transaction is suspicious, the STR must be filed within:','["24 hours", "7 working days", "15 days", "30 days"]'::jsonb,1,'STRs are due within 7 working days of arriving at the conclusion of suspicion.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='GOV'),'A client whose loan is pending sanction sends you an expensive watch. What do you do?','["Accept it — the sanction is not yours to approve", "Accept and declare it after sanction", "Politely decline and report it as per the gifts & conflict-of-interest policy", "Pass it to your mentor"]'::jsonb,2,'Gifts during a pending decision create a conflict of interest; decline and report.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='GOV'),'A customer deposits ₹9.5 lakh in cash on four consecutive days. This pattern is best described as:','["Normal treasury management", "Structuring — a money-laundering red flag", "Sweep-in", "Cash pooling"]'::jsonb,1,'Splitting cash to stay under reporting thresholds is structuring and must be escalated.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='GOV'),'Under the DPDP Act 2023 and bank infosec policy, which action is acceptable?','["Forwarding a client''s balance sheet to your personal Gmail to work from home", "Sharing a CIF list with a vendor on WhatsApp", "Accessing client data only on bank systems for the purpose it was collected", "Keeping printed KYC copies at home"]'::jsonb,2,'Purpose limitation and secure processing on approved systems only.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='PPL'),'The core role of a corporate Relationship Manager is best described as:','["Processing loan documentation", "Single point of accountability for the client, orchestrating product specialists, credit and operations", "Approving credit limits", "Setting treasury rates"]'::jsonb,1,'The RM owns the relationship and coordinates internal specialists.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='PPL'),'In a first meeting with a mid-corporate prospect, the most effective opening is:','["Presenting the full product brochure", "Quoting the lowest rate", "Open questions about their business cycle, cash conversion and growth plans", "Asking for three years'' financials immediately"]'::jsonb,2,'Consultative needs discovery comes before product pitching.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='PPL'),'A client complains that disbursement is delayed. The right first response is:','["Blame operations", "Acknowledge, log it in CRM/grievance system, own the follow-up and give a realistic timeline", "Ask the client to email the branch manager", "Wait for operations to call the client"]'::jsonb,1,'Ownership, logging and a committed timeline protect the relationship and audit trail.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='PPL'),'A complaint of sexual harassment at the workplace is heard by:','["The reporting manager", "The Internal Committee under the POSH Act, 2013", "The branch head", "External auditors"]'::jsonb,1,'The POSH Act mandates an Internal Committee.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='PRD'),'Stock ₹100 Cr, eligible receivables ₹60 Cr, trade creditors ₹40 Cr, margin 25%. Drawing power is:','["₹120 Cr", "₹90 Cr", "₹75 Cr", "₹160 Cr"]'::jsonb,1,'(100 + 60 − 40) × (1 − 0.25) = ₹90 Cr.','CALC_DP',true,3),
((select id from assessments where code='GATE_1'),(select id from modules where code='PRD'),'An exporter needs pre-shipment finance in foreign currency. The suitable product is:','["Cash credit", "Packing Credit in Foreign Currency (PCFC)", "Bank guarantee", "Term loan"]'::jsonb,1,'PCFC funds pre-shipment requirements in foreign currency.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='PRD'),'A Debt Service Coverage Ratio (DSCR) of 1.0x means:','["The company has no debt", "Cash available exactly covers interest and principal due, with no cushion", "The loan is fully secured", "The company is highly profitable"]'::jsonb,1,'Banks typically look for a DSCR comfortably above 1.2–1.3x.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='PRD'),'Interest on a cash credit account is charged on:','["The sanctioned limit", "The daily outstanding balance utilised", "Drawing power", "Stock value"]'::jsonb,1,'CC interest is on utilised daily balances; unused limits may attract commitment charges.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='PRD'),'An importer with USD payables due in 90 days fears INR depreciation. The simplest hedge is:','["Sell USD forward", "Buy USD forward for 90 days", "Open a fixed deposit", "Take a term loan"]'::jsonb,1,'A forward purchase locks the INR cost of the USD payable.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='PRD'),'Financing an anchor company''s dealers against the anchor''s comfort is called:','["Dealer / supply chain finance", "Bill discounting under LC", "Project finance", "Overdraft against FD"]'::jsonb,0,'Dealer finance is a supply-chain finance programme around an anchor.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='PRD'),'A corporate wants receivables from 200 locations pooled to one account daily. Offer:','["Bank guarantee", "Cash management collection services", "Letter of credit", "Working capital demand loan"]'::jsonb,1,'CMS collections consolidate receivables and bring low-cost float.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='PRC'),'A term loan instalment is overdue by 45 days. The account is classified as:','["SMA-0", "SMA-1", "SMA-2", "NPA"]'::jsonb,1,'SMA-1: overdue more than 30 and up to 60 days.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='PRC'),'A cash credit account becomes NPA when it remains out of order (above limit/DP or no credits) continuously for:','["30 days", "60 days", "90 days", "180 days"]'::jsonb,2,'Out-of-order status for 90 days triggers NPA classification.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='PRC'),'Security interest created over a borrower''s assets must be registered with CERSAI within:','["7 days", "30 days", "60 days", "90 days"]'::jsonb,1,'Registration within 30 days of creation protects the bank''s priority.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='PRC'),'The Credit Appraisal Memo (CAM) primarily exists to:','["Market the bank''s products", "Document the risk assessment, structure, terms and recommendation for the sanctioning authority", "Record KYC", "Calculate RM incentives"]'::jsonb,1,'The CAM is the decision document for credit sanction.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='PRC'),'The maker-checker principle means:','["The RM both enters and approves a transaction", "A second independent person verifies and authorises what the first person entered", "Customers check their own statements", "Auditors make all entries"]'::jsonb,1,'Four-eyes control prevents errors and fraud.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='PRC'),'Which is an Early Warning Signal (EWS) an RM should escalate?','["Client opens a new branch", "Repeated delays in stock statements and frequent cheque returns", "Client pays EMI early", "Client asks for a forex quote"]'::jsonb,1,'Delayed statements and bounces signal stress.',null,false,2),
((select id from assessments where code='GATE_1'),(select id from modules where code='PRC'),'Periodic KYC updation for high-risk customers must be done at least once every:','["1 year", "2 years", "8 years", "10 years"]'::jsonb,1,'High risk: 2 years; medium: 8; low: 10 (RBI KYC Master Direction).',null,false,2),
((select id from assessments where code='GATE_2'),(select id from modules where code='PRI'),'Funds Transfer Pricing (FTP) is:','["The rate the customer pays", "The internal rate at which treasury charges/credits business units for funds", "The repo rate", "The penal rate"]'::jsonb,1,'FTP separates interest-rate risk from the RM''s credit spread.',null,false,2),
((select id from assessments where code='GATE_2'),(select id from modules where code='PRI'),'Loan ₹10 Cr at 9.50% with an FTP of 7.00%. Annual net interest income is:','["₹95 lakh", "₹25 lakh", "₹70 lakh", "₹2.5 lakh"]'::jsonb,1,'10 Cr × 2.50% = ₹25 lakh.','CALC_NII',true,3),
((select id from assessments where code='GATE_2'),(select id from modules where code='PRI'),'PD 2%, LGD 45%, EAD ₹50 Cr. Expected loss is:','["₹1 Cr", "₹45 lakh", "₹22.5 lakh", "₹2.25 Cr"]'::jsonb,1,'0.02 × 0.45 × 50 Cr = ₹0.45 Cr.','CALC_EL',true,3),
((select id from assessments where code='GATE_2'),(select id from modules where code='PRI'),'RAROC is calculated as:','["Revenue ÷ total assets", "Risk-adjusted return ÷ economic (allocated) capital", "NII ÷ loans", "Fees ÷ cost"]'::jsonb,1,'(Income − cost − expected loss − tax) ÷ capital.',null,false,2),
((select id from assessments where code='GATE_2'),(select id from modules where code='PRI'),'Relationship RAROC is 11% against a hurdle of 15%. The best RM action is:','["Book it anyway — volume matters", "Reprice and/or add fee and float business to lift returns, or seek a documented deviation", "Drop the client immediately", "Reduce the LGD estimate"]'::jsonb,1,'Below-hurdle deals destroy value unless restructured or justified.',null,true,3),
((select id from assessments where code='GATE_2'),(select id from modules where code='PRI'),'Exposure ₹100 Cr to an AAA-rated corporate (risk weight 20%), CRAR 11.5%. Capital required is:','["₹11.5 Cr", "₹2.3 Cr", "₹20 Cr", "₹0.23 Cr"]'::jsonb,1,'RWA 20 Cr × 11.5% = ₹2.3 Cr.','CALC_CAP',true,3),
((select id from assessments where code='GATE_2'),(select id from modules where code='PRI'),'External-benchmark (EBLR) loans must have the interest rate reset at least once every:','["Month", "Three months", "Year", "Five years"]'::jsonb,1,'RBI requires resets at least once in three months.',null,false,2),
((select id from assessments where code='GATE_2'),(select id from modules where code='PRI'),'LC limit ₹50 Cr, average utilisation 60%, commission 0.50% p.a. Annual LC fee is:','["₹25 lakh", "₹15 lakh", "₹30 lakh", "₹1.5 lakh"]'::jsonb,1,'50 × 60% × 0.5% = ₹0.15 Cr.','CALC_LCFEE',true,3),
((select id from assessments where code='GATE_2'),(select id from modules where code='PRI'),'Pricing below the card rate requires:','["Only RM judgement", "Approval from the authority in the delegation matrix with documented rationale", "Customer''s written request", "No approval if the client is large"]'::jsonb,1,'Deviations are governed and audited.',null,false,2),
((select id from assessments where code='GATE_2'),(select id from modules where code='PRI'),'Raising the spread by 10 bps on a ₹100 Cr loan adds annual NII of:','["₹1 lakh", "₹10 lakh", "₹1 Cr", "₹100 lakh"]'::jsonb,1,'100 Cr × 0.10% = ₹10 lakh.',null,true,3),
((select id from assessments where code='GATE_2'),(select id from modules where code='PNL'),'Average current-account balance ₹20 Cr (0% paid), FTP credit 6%. Annual float value is:','["₹12 lakh", "₹1.2 Cr", "₹20 lakh", "₹6 lakh"]'::jsonb,1,'20 Cr × 6% = ₹1.2 Cr.',null,true,3),
((select id from assessments where code='GATE_2'),(select id from modules where code='PNL'),'Relationship Return on Equity (RoE) is:','["PAT ÷ allocated capital", "Revenue ÷ loans", "NII ÷ deposits", "PBT ÷ assets"]'::jsonb,0,'Profit after tax on the capital the relationship consumes.',null,false,2),
((select id from assessments where code='GATE_2'),(select id from modules where code='PNL'),'A 1% processing fee on a ₹20 Cr term loan earns:','["₹2 lakh", "₹20 lakh", "₹2 Cr", "₹0.2 lakh"]'::jsonb,1,'20 Cr × 1% = ₹0.2 Cr.',null,true,3),
((select id from assessments where code='GATE_2'),(select id from modules where code='PNL'),'Relationship income ₹5 Cr, cost-to-income 40%. Allocated operating cost is:','["₹2 Cr", "₹3 Cr", "₹40 lakh", "₹12.5 Cr"]'::jsonb,0,'5 × 40% = ₹2 Cr.',null,true,3),
((select id from assessments where code='GATE_2'),(select id from modules where code='PNL'),'PBT ₹3 Cr at an effective tax rate of 25.17%. PAT is approximately:','["₹2.25 Cr", "₹0.75 Cr", "₹3.75 Cr", "₹2.75 Cr"]'::jsonb,0,'3 × (1 − 0.2517) ≈ ₹2.24 Cr.',null,true,3),
((select id from assessments where code='GATE_2'),(select id from modules where code='PNL'),'A client''s total annual banking wallet is ₹10 Cr of revenue; your bank earns ₹2 Cr. Wallet share is:','["5%", "20%", "80%", "2%"]'::jsonb,1,'2 ÷ 10 = 20%.',null,true,3),
((select id from assessments where code='GATE_2'),(select id from modules where code='PNL'),'Which lever most improves relationship RoE without adding credit risk?','["Bigger term loan", "Fee and float products: CMS, payroll, trade, forex", "Longer tenor", "Lower margin on stock"]'::jsonb,1,'Fee/float income consumes little or no capital.',null,false,2),
((select id from assessments where code='GATE_2'),(select id from modules where code='PNL'),'Expected loss in a relationship P&L is best treated as:','["Ignored until default", "A running cost of credit, deducted before profit", "Part of fee income", "Part of FTP"]'::jsonb,1,'Risk-adjusted P&L charges expected loss upfront.',null,false,2),
((select id from assessments where code='FINAL'),(select id from modules where code='GOV'),'Shadowing a mentor, a client asks to split ₹40 lakh of cash deposits into four slips of ₹9.9 lakh. You:','["Process it — each slip is under ₹10 lakh", "Decline, inform your mentor and route it for STR review to the Principal Officer", "Ask the client to come back tomorrow", "Split it into 5 slips instead"]'::jsonb,1,'Deliberate structuring must be escalated.',null,false,2),
((select id from assessments where code='FINAL'),(select id from modules where code='PRI'),'A client demands 50 bps below the approved rate; RAROC falls under hurdle. The best response is:','["Agree to keep the client", "Propose CMS, payroll and forex to lift relationship RAROC and seek a documented deviation if still needed", "Refuse and end the meeting", "Lower the PD estimate"]'::jsonb,1,'Price the relationship, not the single loan, within governance.',null,true,3),
((select id from assessments where code='FINAL'),(select id from modules where code='PRC'),'During shadowing you see a client''s stock statements are two months late. You:','["Ignore — renewal is months away", "Flag as an Early Warning Signal, follow up with the client and update CRM", "Stop the CC limit yourself", "Only mention it at year-end"]'::jsonb,1,'Timely EWS action prevents slippage.',null,false,2),
((select id from assessments where code='FINAL'),(select id from modules where code='GOV'),'A client''s HR sends employee Aadhaar and salary data on WhatsApp for payroll set-up. You:','["Forward to operations on WhatsApp", "Ask them to resend via the bank''s secure upload channel and delete the chat copy per policy", "Save it to your phone gallery", "Print and file it"]'::jsonb,1,'Personal data must move only through approved secure channels.',null,false,2),
((select id from assessments where code='FINAL'),(select id from modules where code='PRC'),'At renewal, DSCR has dropped from 1.6x to 1.05x. The appropriate step is:','["Renew as-is", "Deeper cash-flow analysis, revisit structure/covenants and flag in the CAM", "Double the limit", "Close the account"]'::jsonb,1,'Deteriorating coverage needs analysis and structuring, not auto-renewal.',null,false,2),
